import {worldNodes,worldFlows,worldFailures,worldScope} from './world-data.js';
import {ancestors,searchWorld,worldPosition,canStepWorld,validateWorld} from './world-core.js';
const $=id=>document.getElementById(id);
const el=(tag,text,className)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;};
let engine=null,loading=null,active=false,initialized=false,selected='environment',flowId='traffic',stepIndex=0,failureKey=null,playing=false,timer=null,expanded=false;
const flow=()=>({...worldFlows[flowId],id:flowId});
function pause(){playing=false;clearTimeout(timer);timer=null;if(engine)engine.playing=false;$('world-play').textContent='Play flow';}
function select(id,fly=false){if(!worldNodes.some(n=>n.id===id))return;selected=id;renderInspector();renderTree();if(engine){engine.selected=id;engine.dirty=true;if(fly)engine.focus(id);}const node=worldNodes.find(n=>n.id===id);$('world-status').textContent=engine?`Inspecting ${node.label} · modeled educational data`:`Selected ${node.label}. The text explorer works while 3D loads.`;}
function renderInspector(){const n=worldNodes.find(n=>n.id===selected);$('world-node-kind').textContent=(n.minor?'SMALL CONFIGURATION FEATURE':n.kind.toUpperCase())+' · MODELED';$('world-node-title').textContent=n.label;$('world-node-purpose').textContent=n.purpose;$('world-node-input').textContent=n.input;$('world-node-output').textContent=n.output;$('world-node-notes').textContent=n.notes;$('world-node-command').textContent=n.command;$('world-command-panel').hidden=!n.command;$('world-node-reference').href=n.reference;$('world-parent').disabled=!n.parent;$('world-breadcrumb').replaceChildren(...ancestors(worldNodes,selected).flatMap((a,i)=>{const b=el('button',a.label);b.addEventListener('click',()=>select(a.id,true));return i?[el('span','›'),b]:[b];}));const children=worldNodes.filter(child=>child.parent===selected);$('world-node-children').replaceChildren(...(children.length?children.map(child=>{const b=el('button',child.label+' →');b.addEventListener('click',()=>select(child.id,true));return b;}):[el('p','No smaller component is modeled inside this item. Inspect its explanation and connections.')]));}
function renderTree(){const matches=searchWorld(worldNodes,$('world-search').value);$('world-search-count').textContent=`${matches.length} / ${worldNodes.length} components and features`;$('world-tree').replaceChildren(...matches.map(n=>{const b=el('button',undefined,'world-tree-item'+(n.minor?' minor':'')+(n.id===selected?' selected':''));const depth=ancestors(worldNodes,n.id).length-1;b.style.paddingLeft=(7+Math.min(depth,5)*11)+'px';b.append(el('span',(n.minor?'· ':'')+n.label));if(!n.minor)b.append(el('small',n.kind.toUpperCase()));b.setAttribute('aria-current',n.id===selected?'true':'false');b.addEventListener('click',()=>select(n.id,true));return b;}));if(!matches.length)$('world-tree').append(el('p','No matching modeled feature. See the scope list for what is included.'));}
function renderFlow(){const current=flow(),s=current.steps[stepIndex];$('world-flow').value=flowId;$('world-step-kind').textContent=s.kind.toUpperCase();$('world-step-title').textContent=s.title;$('world-step-text').textContent=s.text;$('world-step-packet').textContent=s.packet;$('world-step-counter').textContent=`Step ${stepIndex+1} of ${current.steps.length} · ${worldNodes.find(n=>n.id===s.from).label} → ${worldNodes.find(n=>n.id===s.to).label}`;$('world-prev').disabled=stepIndex===0;$('world-next').disabled=!canStepWorld(current,stepIndex,failureKey,worldFailures);$('world-flow').disabled=!!failureKey;$('world-step-list').replaceChildren(...current.steps.map((s,i)=>{const li=el('li'),b=el('button',`${s.title} — ${s.kind}`);b.addEventListener('click',()=>{pause();goStep(i);});li.append(b);return li;}));engine?.setFlow(flowId,stepIndex,failureKey?worldFailures[failureKey]:null);}
function goStep(index){const current=flow();stepIndex=Math.max(0,Math.min(index,current.steps.length-1));const f=worldFailures[failureKey];if(f&&flowId===f.flow&&stepIndex>f.blockedStep)stepIndex=f.blockedStep;renderFlow();select(current.steps[stepIndex].to,$('world-follow').checked);}
function schedule(){clearTimeout(timer);timer=setTimeout(()=>{if(!playing)return;if(!canStepWorld(flow(),stepIndex,failureKey,worldFailures)){pause();return;}goStep(stepIndex+1);if(stepIndex===flow().steps.length-1)pause();else schedule();},6000);}
async function loadEngine(){if(engine){engine.setActive(active&&!document.hidden);return;}if(loading)return loading;$('world-status').textContent='Loading local 3D engine · text exploration is already available';loading=(async()=>{try{const {KubernetesWorld}=await import('./world-scene.js');engine=new KubernetesWorld($('world-canvas'),$('world-labels'),{onSelect:select,onView:view=>{$('world-level').textContent=view.distance>35?'ENVIRONMENT VIEW':view.distance>16?'CLUSTER / NODE VIEW':view.distance>6?'POD / CONTAINER VIEW':'SMALL FEATURE VIEW';$('world-map-position').style.left=Math.max(2,Math.min(98,(view.target[0]+24)/48*100))+'%';$('world-map-position').style.top=Math.max(2,Math.min(98,(view.target[2]+17)/34*100))+'%';},onScanComplete:()=>{$('world-detail').checked=true;$('world-status').textContent='Illustrative scan complete · 72 modeled components available. Zoom in or search to inspect tiny features.';$('world-scan').disabled=false;},onError:message=>{$('world-error').hidden=false;$('world-error').textContent=message;pause();}});engine.setDetail($('world-detail').checked);if($('world-explode').dataset.enabled==='true')engine.setExploded(true);engine.focus(selected,true);engine.setFlow(flowId,stepIndex,failureKey?worldFailures[failureKey]:null);engine.setActive(active&&!document.hidden);$('world-error').hidden=true;$('world-status').textContent='Drag in any direction · scroll/pinch to zoom · select to inspect';}catch(error){$('world-error').hidden=false;$('world-error').textContent='3D could not start. This view requires WebGL2 and hardware acceleration. The searchable hierarchy, explanations, flow steps and failure exercises still work. Reload the page to retry. Details: '+String(error.message||error);$('world-status').textContent='Text explorer active · 3D unavailable';}finally{loading=null;}})();return loading;}
export function setWorldActive(value){active=value;if(!initialized)return;if(value)loadEngine();else {pause();engine?.setActive(false);}}
export function initializeWorldUI(){if(initialized)return;initialized=true;validateWorld(worldNodes,worldFlows,worldFailures);
 $('world-flow').replaceChildren(...Object.entries(worldFlows).map(([id,f])=>{const o=el('option',f.label);o.value=id;return o;}));$('world-failure').replaceChildren(...Object.entries(worldFailures).map(([id,f])=>{const o=el('option',f.label);o.value=id;return o;}));$('world-failure').value='env';$('world-detail').checked=false;$('world-follow').checked=false;
 $('world-search').addEventListener('input',renderTree);$('world-focus').addEventListener('click',()=>engine?.focus(selected));$('world-parent').addEventListener('click',()=>{const n=worldNodes.find(n=>n.id===selected);if(n.parent)select(n.parent,true);});$('world-home').addEventListener('click',()=>{select('environment');engine?.overview();});
 $('world-help').addEventListener('click',()=>{$('world-help-panel').hidden=!$('world-help-panel').hidden;$('world-help').setAttribute('aria-expanded',String(!$('world-help-panel').hidden));});$('world-detail').addEventListener('change',()=>engine?.setDetail($('world-detail').checked));$('world-explode').addEventListener('click',()=>{const pressed=$('world-explode').dataset.enabled!=='true';$('world-explode').dataset.enabled=String(pressed);$('world-explode').setAttribute('aria-pressed',String(pressed));engine?.setExploded(pressed);});$('world-expand').addEventListener('click',()=>{expanded=!expanded;$('world-workspace').classList.toggle('expanded',expanded);$('world-expand').setAttribute('aria-expanded',String(expanded));$('world-expand').textContent=expanded?'Exit expanded view':'Expand';engine?.resize();});
 $('world-scan').addEventListener('click',()=>{if(!engine){$('world-status').textContent='3D is unavailable or still loading. All modeled features are searchable in the text explorer.';return;}$('world-scan').disabled=true;select('environment');$('world-status').textContent='Illustrative scan revealing the modeled system · no real infrastructure discovery';engine.scan();});
 const actions={'world-turn-left':()=>engine?.orbit(-.18,0),'world-turn-right':()=>engine?.orbit(.18,0),'world-tilt-up':()=>engine?.orbit(0,-.14),'world-tilt-down':()=>engine?.orbit(0,.14),'world-zoom-in':()=>engine?.zoom(.78),'world-zoom-out':()=>engine?.zoom(1.28),'world-pan-left':()=>engine?.pan(-1,0),'world-pan-right':()=>engine?.pan(1,0),'world-pan-up':()=>engine?.pan(0,1),'world-pan-down':()=>engine?.pan(0,-1)};Object.entries(actions).forEach(([id,fn])=>$(id).addEventListener('click',fn));
 $('world-canvas').addEventListener('keydown',e=>{const key=e.key,fn=key==='ArrowLeft'?actions['world-turn-left']:key==='ArrowRight'?actions['world-turn-right']:key==='ArrowUp'?actions['world-tilt-up']:key==='ArrowDown'?actions['world-tilt-down']:key==='+'||key==='='?actions['world-zoom-in']:key==='-'?actions['world-zoom-out']:null;if(fn){e.preventDefault();fn();}});
 $('world-flow').addEventListener('change',()=>{pause();flowId=$('world-flow').value;stepIndex=0;renderFlow();});$('world-next').addEventListener('click',()=>{pause();if(canStepWorld(flow(),stepIndex,failureKey,worldFailures))goStep(stepIndex+1);});$('world-prev').addEventListener('click',()=>{pause();goStep(stepIndex-1);});$('world-play').addEventListener('click',()=>{if(playing){pause();return;}if(failureKey&&!canStepWorld(flow(),stepIndex,failureKey,worldFailures)){$('world-repair-feedback').textContent='Resolve the simulated failure with the evidence below before continuing.';return;}if(stepIndex===flow().steps.length-1)goStep(0);playing=true;if(engine)engine.playing=true;$('world-play').textContent='Pause flow';schedule();});
 $('world-inject').addEventListener('click',()=>{pause();failureKey=$('world-failure').value;const f=worldFailures[failureKey];flowId=f.flow;stepIndex=f.blockedStep;$('world-failure-content').hidden=false;$('world-failure-evidence').textContent=f.evidence;$('world-repair-feedback').textContent='';$('world-repair-options').replaceChildren(...f.options.map((text,i)=>{const b=el('button',text,'choice');b.addEventListener('click',()=>{const good=i===f.correct;b.classList.add(good?'correct':'wrong');$('world-repair-feedback').textContent=good?'Recovered in this simulation. '+f.explanation:'That does not address the evidence. Try another action.';if(good){failureKey=null;$('world-repair-options').querySelectorAll('button').forEach(b=>b.disabled=true);renderFlow();}});return b;}));renderFlow();select(f.node,true);});
 $('world-included').replaceChildren(...worldScope.included.map(text=>el('li',text)));$('world-not-included').replaceChildren(...worldScope.notIncluded.map(text=>el('li',text)));
 for(const n of worldNodes.filter(n=>n.parent==='environment'||n.parent==='cluster')){const p=worldPosition(worldNodes,n.id),b=el('button',undefined,'world-map-point');b.style.left=(p[0]+24)/48*100+'%';b.style.top=(p[2]+17)/34*100+'%';b.title=n.label;b.setAttribute('aria-label','Focus '+n.label);b.addEventListener('click',()=>select(n.id,true));$('world-map').append(b);}
 document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();engine?.setActive(active&&!document.hidden);});renderTree();renderInspector();renderFlow();if(active)loadEngine();
}
